function ensureLongTaskUi(){if(document.getElementById('kcLongTaskOverlay'))return;const st=document.createElement('style');st.textContent=`#kcLongTaskOverlay{position:fixed;inset:0;z-index:120000;background:rgba(30,20,16,.54);display:flex;align-items:center;justify-content:center;padding:22px}#kcLongTaskOverlay.hidden{display:none}#kcLongTaskCard{width:min(560px,94vw);background:#fffaf0;border:1px solid #d7c39b;border-radius:18px;box-shadow:0 24px 70px rgba(0,0,0,.3);padding:22px}#kcLongTaskCard h2{margin:0 0 8px;color:#6f1728;font-size:1.35rem}#kcLongTaskLabel{color:#5d554f;margin:0 0 14px}#kcLongTaskBar{height:15px;border-radius:999px;background:#e7ded0;overflow:hidden}#kcLongTaskFill{height:100%;width:0;background:linear-gradient(90deg,#7c1730,#c39a43);transition:width .16s ease}#kcLongTaskMeta{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:10px;font-size:.92rem;color:#655c55}#kcLongTaskPct{font-weight:800;color:#6f1728}`;document.head.appendChild(st);const ov=document.createElement('div');ov.id='kcLongTaskOverlay';ov.className='hidden';ov.innerHTML='<div id="kcLongTaskCard" role="status" aria-live="polite"><h2 id="kcLongTaskTitle">Vorgang läuft</h2><p id="kcLongTaskLabel">Bitte warten …</p><div id="kcLongTaskBar"><div id="kcLongTaskFill"></div></div><div id="kcLongTaskMeta"><span id="kcLongTaskPct">0 %</span><span id="kcLongTaskElapsed">Laufzeit 0,0 s</span><span id="kcLongTaskEta">Restzeit wird berechnet …</span></div></div>';document.body.appendChild(ov)}
function formatTaskSeconds(ms){return `${Math.max(0,ms)/1000<10?(Math.max(0,ms)/1000).toFixed(1):Math.round(Math.max(0,ms)/1000)} s`}
function startLongTask({title='Vorgang läuft',total=100,label='Bitte warten …',showAfter=180}={}){ensureLongTaskUi();const ov=$('kcLongTaskOverlay'),started=performance.now(),safeTotal=Math.max(1,Number(total)||1);let done=0,shown=false,closed=false,timer=setTimeout(()=>show(),Math.max(0,showAfter)),ticker=setInterval(()=>{if(shown&&!closed)paint()},250);function show(){if(closed||shown)return;shown=true;ov.classList.remove('hidden');$('kcLongTaskTitle').textContent=title;$('kcLongTaskLabel').textContent=label;paint()}function paint(extraLabel){if(extraLabel)$('kcLongTaskLabel').textContent=extraLabel;const pct=Math.max(0,Math.min(100,done/safeTotal*100)),elapsed=performance.now()-started;$('kcLongTaskFill').style.width=pct.toFixed(1)+'%';$('kcLongTaskPct').textContent=`${Math.round(pct)} %`;$('kcLongTaskElapsed').textContent=`Laufzeit ${formatTaskSeconds(elapsed)}`;const eta=done>0&&done<safeTotal?elapsed/done*(safeTotal-done):0;$('kcLongTaskEta').textContent=done>=safeTotal?'Restzeit 0 s':done>0?`ca. ${formatTaskSeconds(eta)} Restzeit`:'Restzeit wird berechnet …';return {pct,elapsed,eta}}function stop(){clearTimeout(timer);clearInterval(ticker)}return {update(value,nextLabel){done=Math.max(0,Math.min(safeTotal,Number(value)||0));if(shown)paint(nextLabel);},step(nextLabel){done=Math.min(safeTotal,done+1);if(shown)paint(nextLabel);},show,finish(text='Fertig'){done=safeTotal;stop();if(!shown&&showAfter===0)show();if(shown){paint(text);setTimeout(()=>{if(!closed){ov.classList.add('hidden');closed=true}},380)}else closed=true;return {elapsedMs:performance.now()-started};},error(text='Vorgang abgebrochen'){stop();show();$('kcLongTaskLabel').textContent=text;$('kcLongTaskEta').textContent='Abgebrochen';setTimeout(()=>{ov.classList.add('hidden');closed=true},1200);return {elapsedMs:performance.now()-started};}}}
K.longTask={start:startLongTask};
function syncLed(){const el=$('supabaseStatusLed');if(!el||!K.sync)return;const st=K.sync.state.status,auth=K.supabaseConnection?.state?.authStatus;let cls='error';if(auth==='authenticated'&&st==='ready')cls='ok';if(st==='maintenance'||st==='syncing'||st==='checking'||st==='configured'||auth==='authenticating')cls='maintenance';if(auth==='error'||st==='error'||st==='offline')cls='error';el.className='led led-status '+cls;K.state.supabaseConnected=cls==='ok';}
