  $('userClose').onclick=closeModal;
  if($('userSeen'))$('userSeen').onclick=async()=>{try{K.markPlanSeen(me.personId);closeModal();msg(`✓ ${me.name}: veröffentlichter Sollplan als gesehen markiert.`,'success');await persist();}catch(e){msg('✕ '+e.message,'error')}};
